--
-- namegenerators/ib1.lua
--
-- IronBrew1-style sequential name generator.
-- Produces names in strict sequential order: a, b, c, ..., z,
-- then aa, ab, ..., zz, then aaa, aab, ... (lowercase only, no digits).
--
-- No shuffle, no randomness — the first 26 names are always a–z.
-- This guarantees the 13 wrapper-function params generated by
-- WrapInFunction/ReturnTable come out as a,b,c,d,e,f,g,h,i,j,k,l,m
-- which matches the IronBrew1 aesthetic.

local ALPHA = {}
for c in ("abcdefghijklmnopqrstuvwxyz"):gmatch(".") do
    ALPHA[#ALPHA+1] = c
end
local N = #ALPHA  -- 26

local _gid = 0

local function idToName(id)
    if id < N then
        return ALPHA[id + 1]
    elseif id < N + N * N then
        local rem = id - N
        local d1  = math.floor(rem / N) % N
        local d2  = rem % N
        return ALPHA[d1 + 1] .. ALPHA[d2 + 1]
    else
        local rem = id - N - N * N
        local d1  = math.floor(rem / (N * N)) % N
        local d2  = math.floor(rem / N) % N
        local d3  = rem % N
        return ALPHA[d1 + 1] .. ALPHA[d2 + 1] .. ALPHA[d3 + 1]
    end
end

local function generateName(id, scope)
    local name = idToName(_gid)
    _gid = _gid + 1
    return name
end

local function prepare(ast)
    _gid = 0
end

return {
    generateName = generateName,
    prepare      = prepare,
}
